	('editorial', 'Editorial', 'Story-Driven. Stylised. Striking.', 'A cinematic, magazine-worthy aesthetic. Expressive and fashion-forward — stand out with personality and mood.', '["outdoor-fashion-1.webp", "outdoor-fashion-2.webp", "outdoor-fashion-3.webp", "outdoor-fashion-4.webp", "outdoor-fashion-4.webp"]', '{male,female}', '{plain-light,plain-dark,plain-orange,plain-blue,plain-teal}', '{hoodie,shirt,polo,henley,jacket,fishermans-jumper}', '{#000000,#FFFFFF,#2A9D47,#3B82F6,#FF7F39,#D22D2D,#FC84E2,#A28DF7,#6B7280,#4F46E5}', '{"de": {"name": "Editorial", "tagline": "Erzählerisch. Stilisiert. Eindrucksvoll.", "description": "Eine filmische, magazinwürdige Ästhetik. Expressiv und modisch — stechen Sie mit Persönlichkeit und Stimmung hervor."}, "es": {"name": "Editorial", "tagline": "Narrativo. Estilizado. Impactante.", "description": "Una estética cinematográfica digna de revista. Expresivo y vanguardista — destaca con personalidad y ambiente."}, "fr": {"name": "Éditorial", "tagline": "Narratif. Stylisé. Saisissant.", "description": "Une esthétique cinématographique digne des magazines. Expressif et avant-gardiste — démarquez-vous avec personnalité et ambiance."}, "it": {"name": "Editoriale", "tagline": "Narrativo. Stilizzato. Impressionante.", "description": "Un''estetica cinematografica degna di una rivista. Espressivo e all''avanguardia — distinguiti con personalità e atmosfera."}, "ja": {"name": "エディトリアル", "tagline": "ストーリー性。様式的。印象的。", "description": "映画のような雑誌品質の美学。表現力豊かでファッション性の高い — 個性と雰囲気で際立ちます。"}, "nl": {"name": "Editorial", "tagline": "Verhalend. Gestileerd. Opvallend.", "description": "Een cinematografische, magazine-waardige esthetiek. Expressief en vooruitstrevend — val op met persoonlijkheid en sfeer."}, "pt": {"name": "Editorial", "tagline": "Narrativo. Estilizado. Impactante.", "description": "Uma estética cinematográfica digna de revista. Expressivo e vanguardista — destaque-se com personalidade e atmosfera."}, "zh": {"name": "杂志风格", "tagline": "叙事性。风格化。引人注目。", "description": "电影般的杂志级美学。富有表现力和前卫感 — 以独特个性和氛围脱颖而出。"}}', '2025-05-03 23:44:34.330977+00', '2025-05-03 23:44:34.330977+00'),
	('corporate', 'Corporate', 'Professional. Approachable. Trusted.', 'Professional and approachable, perfect for LinkedIn, team pages, and pitch decks — designed to make a confident first impression.', '["business-2.webp", "business-1.webp", "business-3.webp", "business-1.webp", "business-3.webp"]', '{male,female}', '{plain-light,plain-dark,plain-orange,plain-blue,plain-teal}', '{suit-jacket-shirt,shirt,polo,henley,jacket}', '{#000000,#FFFFFF,#2A9D47,#3B82F6,#FF7F39,#D22D2D,#FC84E2,#A28DF7,#6B7280,#4F46E5}', '{"de": {"name": "Business", "tagline": "Professionell. Zugänglich. Vertrauenswürdig.", "description": "Professionell und zugänglich, perfekt für LinkedIn, Teamseiten und Pitch-Decks — entwickelt für einen selbstbewussten ersten Eindruck."}, "es": {"name": "Corporativo", "tagline": "Profesional. Accesible. Confiable.", "description": "Profesional y accesible, perfecto para LinkedIn, páginas de equipo y presentaciones — diseñado para dar una primera impresión segura."}, "fr": {"name": "Corporate", "tagline": "Professionnel. Accessible. Fiable.", "description": "Professionnel et accessible, parfait pour LinkedIn, les pages d''équipe et les présentations — conçu pour donner une première impression assurée."}, "it": {"name": "Corporate", "tagline": "Professionale. Accessibile. Affidabile.", "description": "Professionale e accessibile, perfetto per LinkedIn, pagine del team e presentazioni — progettato per dare una prima impressione sicura."}, "ja": {"name": "コーポレート", "tagline": "プロフェッショナル。親しみやすい。信頼感。", "description": "プロフェッショナルで親しみやすい、LinkedIn、チームページ、ピッチデッキに最適 — 自信に満ちた第一印象を作るためにデザインされました。"}, "nl": {"name": "Zakelijk", "tagline": "Professioneel. Benaderbaar. Betrouwbaar.", "description": "Professioneel en toegankelijk, perfect voor LinkedIn, teampagina''s en pitch decks — ontworpen om een zelfverzekerde eerste indruk te maken."}, "pt": {"name": "Corporativo", "tagline": "Profissional. Acessível. Confiável.", "description": "Profissional e acessível, perfeito para LinkedIn, páginas de equipe e apresentações — projetado para criar uma primeira impressão confiante."}, "zh": {"name": "商务风格", "tagline": "专业。平易近人。值得信赖。", "description": "专业且平易近人，完美适用于领英、团队页面和演示文稿 — 旨在创造自信的第一印象。"}}', '2025-05-03 23:44:34.330977+00', '2025-05-03 23:44:34.330977+00'),
	('studio', 'Studio', 'Polished. Professional. Powerful.', 'Step into the spotlight with Studio style — clean, high-impact headshots perfect for portfolios, castings, and personal branding.', '["studio-1.webp", "studio-2.webp", "studio-3.webp", "studio-1.webp", "studio-2.webp"]', '{male,female}', '{plain-light,plain-dark,plain-orange,plain-blue,plain-teal}', '{shirt,polo,henley,jacket,fishermans-jumper}', '{#000000,#FFFFFF,#2A9D47,#3B82F6,#FF7F39,#D22D2D,#FC84E2,#A28DF7,#6B7280,#4F46E5}', '{"de": {"name": "Studio", "tagline": "Poliert. Professionell. Kraftvoll.", "description": "Treten Sie mit dem Studio-Stil ins Rampenlicht — klare, wirkungsvolle Portraits, perfekt für Portfolios, Castings und persönliches Branding."}, "es": {"name": "Estudio", "tagline": "Refinado. Profesional. Poderoso.", "description": "Paso al centro de la cámara con el estilo Estudio — imágenes de cabecera limpias y de alto impacto perfectas para portafolios, casting y branding personal."}, "fr": {"name": "Studio", "tagline": "Raffiné. Professionnel. Puissant.", "description": "Entrez dans la lumière avec le style Studio — des portraits nets et percutants, parfaits pour les portfolios, les castings et l''image de marque personnelle."}, "it": {"name": "Studio", "tagline": "Raffinato. Professionale. Potente.", "description": "Entra sotto i riflettori con lo stile Studio — ritratti puliti e d''impatto perfetti per portfolio, casting e personal branding."}, "ja": {"name": "スタジオ", "tagline": "洗練。プロフェッショナル。パワフル。", "description": "スタジオスタイルでスポットライトを浴びましょう — ポートフォリオ、キャスティング、パーソナルブランディングに最適なクリーンで印象的なヘッドショット。"}, "nl": {"name": "Studio", "tagline": "Gepolijst. Professioneel. Krachtig.", "description": "Stap in de spotlight met de Studio-stijl — strakke, impactvolle headshots perfect voor portfolio''s, castings en personal branding."}, "pt": {"name": "Estúdio", "tagline": "Refinado. Profissional. Poderoso.", "description": "Entre sob os holofotes com o estilo Estúdio — fotos limpas e de alto impacto perfeitas para portfólios, testes e marca pessoal."}, "zh": {"name": "工作室风格", "tagline": "精致。专业。有力。", "description": "以工作室风格步入聚光灯下 — 干净、具有冲击力的头像照片，完美适用于作品集、试镜和个人品牌塑造。"}}', '2025-05-03 23:44:34.330977+00', '2025-05-03 23:44:34.330977+00');
